//! `rok-sqlc init --template <NAME>`: copies a ready-made project, a
//! directory of `templates/` embedded in the binary by `build.rs`, into a
//! project, each file only when absent. rok-sqlc's generated files
//! (`@generated by rok-sqlc` on their first line) are left out: `rok-sqlc g`
//! writes them. Other files, such as the template's pinned `Cargo.lock`, are
//! copied. Adding a file to a template's directory is all it takes to ship
//! it.

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};

use super::{Scaffolded, crate_name, declared_crate, is_cargo_default_main};
use crate::output::write_absent;
use crate::report::display_path;

/// A template file, as `build.rs` embeds it.
struct File {
    /// Its path in the template, with `/`.
    path: &'static str,
    /// Its contents.
    bytes: &'static [u8],
}

/// A template directory of `templates/` and its files, as `build.rs`
/// embeds it.
struct Embedded {
    /// The directory's name.
    dir: &'static str,
    files: &'static [File],
}

/// Every template directory of `templates/`.
const EMBEDDED: &[Embedded] = include!(concat!(env!("OUT_DIR"), "/templates.rs"));

/// A template `--template` names.
struct Template {
    /// The name `--template` takes.
    name: &'static str,
    /// Its directory of `templates/`.
    dir: &'static str,
}

/// The templates `--template` names.
const TEMPLATES: &[Template] = &[Template {
    name: "actix",
    dir: "actix-api",
}];

/// The names `--template` takes.
pub fn names() -> impl Iterator<Item = &'static str> {
    TEMPLATES.iter().map(|template| template.name)
}

/// The embedded files of the template `name`.
fn files(name: &str) -> Result<&'static [File]> {
    let embedded = TEMPLATES
        .iter()
        .find(|template| template.name == name)
        .and_then(|template| {
            EMBEDDED
                .iter()
                .find(|embedded| embedded.dir == template.dir)
        });
    match embedded {
        Some(embedded) => Ok(embedded.files),
        None => bail!(
            "unknown template `{name}`; the templates are: {}",
            names().collect::<Vec<_>>().join(", ")
        ),
    }
}

/// The suffix [`destination`] removes.
const TEMPLATE_SUFFIX: &str = ".template";

/// Where a template file goes in the project: its own path, but
/// `<path>.template` goes to `<path>`. Cargo leaves a directory holding a
/// `Cargo.toml` (another package) out of the published crate, so a
/// template's manifest is checked in as `Cargo.toml.template`.
fn destination(path: &str) -> &str {
    path.strip_suffix(TEMPLATE_SUFFIX).unwrap_or(path)
}

/// rok-sqlc's generated marker, in any comment syntax.
const GENERATED_MARKER: &str = "@generated by rok-sqlc";

/// Whether `text` is one of rok-sqlc's generated files: [`GENERATED_MARKER`]
/// on its first line. Other tools' generated files (cargo's `Cargo.lock`)
/// are not.
fn is_generated(text: &str) -> bool {
    text.lines()
        .next()
        .is_some_and(|line| line.contains(GENERATED_MARKER))
}

/// `text` with each path through the crate `from` (`from::` as a whole path
/// segment) through `to` instead. `my_from::` names another crate and stays.
fn rename_crate(text: &str, from: &str, to: &str) -> String {
    let pattern = format!("{from}::");
    let mut renamed = String::with_capacity(text.len());
    let mut copied = 0;
    for (at, _) in text.match_indices(&pattern) {
        let starts_segment = !text[..at]
            .chars()
            .next_back()
            .is_some_and(|c| c.is_alphanumeric() || c == '_');
        if starts_segment {
            renamed.push_str(&text[copied..at]);
            renamed.push_str(to);
            copied = at + from.len();
        }
    }
    renamed.push_str(&text[copied..]);
    renamed
}

/// The template's files to copy under `dir`, each its path in the project
/// and its text with `\n` line endings: all but rok-sqlc's generated ones.
/// When the project's library crate is `krate` and the template's (its
/// `Cargo.toml`'s) another, the Rust files name `krate` instead.
fn plan(dir: &Path, files: &[File], krate: Option<&str>) -> Result<Vec<(PathBuf, String)>> {
    let template_crate = files
        .iter()
        .find(|file| destination(file.path) == "Cargo.toml")
        .and_then(|file| declared_crate(&String::from_utf8_lossy(file.bytes)));
    let rename = match (template_crate, krate) {
        (Some(from), Some(to)) if from != to => Some((from, to)),
        _ => None,
    };
    let mut planned = Vec::new();
    for file in files {
        let text = std::str::from_utf8(file.bytes)
            .with_context(|| format!("template file `{}` is not UTF-8", file.path))?
            .replace("\r\n", "\n");
        if is_generated(&text) {
            continue;
        }
        let text = match &rename {
            Some((from, to)) if file.path.ends_with(".rs") => rename_crate(&text, from, to),
            _ => text,
        };
        planned.push((dir.join(destination(file.path)), text));
    }
    Ok(planned)
}

/// Copies the template `name` into `dir`, keeping every file that exists
/// but cargo's untouched default `src/main.rs`.
pub fn init_template(dir: &Path, name: &str) -> Result<Scaffolded> {
    let files = files(name)?;
    let krate = dir.join("Cargo.toml").is_file().then(|| crate_name(dir));
    let planned = plan(dir, files, krate.as_deref())?;
    let main = dir.join("src/main.rs");
    let replaced_default_main = planned.iter().any(|(path, _)| *path == main)
        && fs::read_to_string(&main).is_ok_and(|text| is_cargo_default_main(&text));
    if replaced_default_main {
        fs::remove_file(&main)
            .with_context(|| format!("failed to replace `{}`", display_path(&main)))?;
    }
    let written = write_absent(&planned)?;
    let manifest = dir.join("Cargo.toml");
    Ok(Scaffolded {
        wrote_manifest: written.contains(&manifest),
        written,
        replaced_default_main,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_template_is_embedded() {
        for name in names() {
            let files = files(name).unwrap_or_else(|err| panic!("{err}"));
            assert!(!files.is_empty(), "template `{name}` has no files");
        }
    }

    /// rok-sqlc's generated files are left out; cargo's `Cargo.lock`, also
    /// `@generated`, is the template's pinned lock and is copied.
    #[test]
    fn rok_sqlcs_generated_files_are_left_out_and_line_endings_normalized() -> Result<()> {
        let files = &[
            File {
                path: "Cargo.lock",
                bytes: b"# This file is automatically @generated by Cargo.\n",
            },
            File {
                path: "src/db/mod.rs",
                bytes: b"// @generated by rok-sqlc. Do not edit by hand.\n",
            },
            File {
                path: "src/features/README.md",
                bytes: b"<!-- @generated by rok-sqlc. Do not edit by hand. -->\n",
            },
            File {
                path: "README.md",
                bytes: b"# App\r\n\r\nFiles marked @generated are rok-sqlc's.\r\n",
            },
        ];
        let planned = plan(Path::new("p"), files, None)?;
        assert_eq!(
            planned,
            [
                (
                    PathBuf::from("p/Cargo.lock"),
                    "# This file is automatically @generated by Cargo.\n".to_owned()
                ),
                (
                    PathBuf::from("p/README.md"),
                    "# App\n\nFiles marked @generated are rok-sqlc's.\n".to_owned()
                ),
            ]
        );
        Ok(())
    }

    /// The template's Rust files name its library crate; copied into a
    /// project with a crate of its own, they name the project's. Its
    /// manifest is copied as `Cargo.toml`.
    #[test]
    fn rust_files_name_the_projects_crate() -> Result<()> {
        let files = &[
            File {
                path: "Cargo.toml.template",
                bytes: b"[package]\nname = \"actix-api\"\n",
            },
            File {
                path: "src/main.rs",
                bytes: b"use actix_api::{app, config};\n",
            },
            File {
                path: "README.md",
                bytes: b"`actix_api::app`\n",
            },
        ];
        let planned = plan(Path::new("p"), files, Some("shop"))?;
        assert_eq!(planned[1].1, "use shop::{app, config};\n");
        assert_eq!(planned[2].1, "`actix_api::app`\n");
        let planned = plan(Path::new("p"), files, None)?;
        assert_eq!(planned[0].0, Path::new("p/Cargo.toml"));
        assert_eq!(planned[1].1, "use actix_api::{app, config};\n");
        Ok(())
    }

    /// Only a whole path segment naming the crate is renamed: a crate whose
    /// name merely ends with it is another crate.
    #[test]
    fn the_crate_rename_matches_whole_path_segments_only() {
        assert_eq!(
            rename_crate(
                "use actix_api::app;\nuse my_actix_api::x;\nlet y = ::actix_api::y;\n",
                "actix_api",
                "shop"
            ),
            "use shop::app;\nuse my_actix_api::x;\nlet y = ::shop::y;\n"
        );
    }

    #[test]
    fn an_unknown_template_lists_the_valid_ones() {
        let err = files("axum").err().map(|err| err.to_string());
        assert_eq!(
            err.as_deref(),
            Some("unknown template `axum`; the templates are: actix")
        );
    }
}
